cd /testbed && python3 - <<'PY'
from pathlib import Path

path = Path('axum/src/routing/tests/fallback.rs')
text = path.read_text()
text += '''
#[crate::test]
async fn fallback_service_with_nested_static_file_server() {
    let routes_static = Router::new().nest_service(
        "/",
        get_service(tower_http::services::ServeDir::new(".")),
    );
    let app = Router::new().fallback_service(routes_static);
    let client = TestClient::new(app);

    let res = client.get("/README.md").send().await;
    assert_eq!(res.status(), StatusCode::OK);
    assert_eq!(res.text().await, include_str!("../../../README.md"));

    let res = client.head("/README.md").send().await;
    assert_eq!(res.status(), StatusCode::OK);
    assert!(res.text().await.is_empty());

    let res = client.get("/does-not-exist").send().await;
    assert_eq!(res.status(), StatusCode::NOT_FOUND);
}
'''
path.write_text(text)

path = Path('axum/src/extract/matched_path.rs')
text = path.read_text()
needle = '''    #[crate::test]
    async fn extracting_on_handler_in_nested_router() {'''
assert text.count(needle) == 1
text = text.replace(needle, '''    #[crate::test]
    async fn cannot_extract_matched_path_in_fallback() {
        async fn fallback(path: Option<MatchedPath>) {
            assert!(path.is_none());
        }

        let apps = [
            Router::new().fallback(fallback),
            Router::new()
                .nest("/nested", Router::new().fallback(fallback))
                .fallback(fallback),
            Router::new()
                .nest_service("/nested", Router::new().fallback(fallback))
                .fallback(fallback),
        ];

        for app in apps {
            let client = TestClient::new(app);
            for path in ["/", "/missing", "/nested", "/nested/", "/nested/missing"] {
                let res = client.get(path).send().await;
                assert_eq!(res.status(), StatusCode::OK);
            }
        }
    }

    #[crate::test]
    async fn extracting_on_handler_in_fallback_router() {
        let app = Router::new().fallback_service(Router::new().route(
            "/:a",
            get(|path: MatchedPath| async move { path.as_str().to_owned() }),
        ));

        let client = TestClient::new(app);

        let res = client.get("/foo").send().await;
        assert_eq!(res.status(), StatusCode::OK);
        assert_eq!(res.text().await, "/:a");
    }

''' + needle)
path.write_text(text)
PY
RUSTFLAGS=-Awarnings cargo test --package axum --lib -- fallback

